//! Types shared by the analysis and the Cloudflare backend. TypeScript mirrors are
//! generated by ts-rs into `cloud/bindings/` (`cargo test --workspace`).

use serde::{Deserialize, Serialize};
use ts_rs::TS;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum ExplainMode {
    /// `EXPLAIN ANALYZE` — executes the statement inside a rolled-back transaction.
    Analyze,
    /// Plain `EXPLAIN` — planner estimates only, never executes.
    Estimate,
}

impl ExplainMode {
    pub fn as_str(self) -> &'static str {
        match self {
            ExplainMode::Analyze => "analyze",
            ExplainMode::Estimate => "estimate",
        }
    }
    pub fn parse(s: &str) -> Self {
        if s == "estimate" { ExplainMode::Estimate } else { ExplainMode::Analyze }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum WarningKind {
    MissingIndex,
    SeqScanLarge,
    RowEstimateError,
    SortSpill,
    HashSpill,
    NestedLoopBlowup,
    HeapFetches,
    JitOverhead,
    IoBound,
    SerializeHeavy,
    /// A sort that has to read all of its input before returning a row (MySQL filesort,
    /// MongoDB in-memory SORT) where an index could return rows already ordered.
    BlockingSort,
    /// An index scan whose results are mostly thrown away by a later filter.
    UnselectiveIndex,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum WarningSeverity {
    Error,
    Warning,
    Info,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct PlanWarning {
    pub kind: WarningKind,
    pub severity: WarningSeverity,
    pub message: String,
}

/// How a suggestion was backed up by the model.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Evidence {
    /// Executed with EXPLAIN ANALYZE (real timings).
    Measured,
    /// Planner estimate only, e.g. a HypoPG hypothetical index.
    Estimated,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum SuggestionSeverity {
    High,
    Medium,
    Low,
}

/// One statement execution seen by the proxy.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct CapturedStatement {
    /// Order of completion within the capture.
    pub seq: u32,
    /// Proxy connection number (one per client connection).
    pub conn: u32,
    /// Start time, ms since the capture started.
    pub at_ms: f64,
    /// Time from the request reaching the proxy to the response finishing, ms.
    pub duration_ms: f64,
    pub fingerprint: String,
    /// The statement as sent, with its literals; comment tags removed.
    pub sql: String,
    /// Bind parameters for `$1…$n` (null = SQL NULL).
    pub params: Vec<Option<String>>,
    pub rows: f64,
    /// Bytes of result data returned to the application.
    pub bytes: f64,
    pub error: Option<String>,
    /// Request / trace the statement belongs to, from comment tags.
    pub unit: Option<String>,
    /// Where it came from in the application (file:line, route, controller#action).
    pub origin: Option<String>,
    /// The HTTP route or job it ran for, from comment tags.
    pub route: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum StatementKind {
    Select,
    Insert,
    Update,
    Delete,
    Other,
}

/// The ORM that generated the statements, recognised from their SQL style or tags.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Orm {
    Sequelize,
    Prisma,
    TypeOrm,
    Drizzle,
    MikroOrm,
    Objection,
    /// Knex, or Kysely: the two build byte-identical SQL.
    Knex,
    Django,
    ActiveRecord,
    SqlAlchemy,
    Hibernate,
}

impl Orm {
    pub fn label(self) -> &'static str {
        match self {
            Orm::Sequelize => "Sequelize",
            Orm::Prisma => "Prisma",
            Orm::TypeOrm => "TypeORM",
            Orm::Drizzle => "Drizzle",
            Orm::MikroOrm => "MikroORM",
            Orm::Objection => "Objection.js",
            Orm::Knex => "Knex / Kysely",
            Orm::Django => "Django ORM",
            Orm::ActiveRecord => "Active Record",
            Orm::SqlAlchemy => "SQLAlchemy",
            Orm::Hibernate => "Hibernate",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct OriginCount {
    pub origin: String,
    pub count: u32,
}

/// All executions of one statement shape (same fingerprint).
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct FingerprintStat {
    pub fingerprint: String,
    /// Normalized text: literals and parameters replaced by `?`.
    pub normalized: String,
    /// The slowest execution as sent (literals intact, comment tags removed).
    pub sample_sql: String,
    pub sample_params: Vec<Option<String>>,
    pub kind: StatementKind,
    pub tables: Vec<String>,
    pub calls: u32,
    pub total_ms: f64,
    pub mean_ms: f64,
    pub p50_ms: f64,
    pub p95_ms: f64,
    pub max_ms: f64,
    pub rows: f64,
    pub max_rows: f64,
    pub bytes: f64,
    pub errors: u32,
    /// Share of all captured statement time, 0–1.
    pub share: f64,
    pub origins: Vec<OriginCount>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum FindingKind {
    /// The same SELECT run once per row of an earlier result, with different values.
    NPlusOne,
    /// The identical statement (same values) repeated back to back.
    DuplicateQuery,
    /// INSERT / UPDATE / DELETE issued one row at a time in a loop.
    LoopedWrites,
    /// The plan has a problem: a large sequential scan, a missing index, a spill…
    PlanIssue,
    SlowQuery,
    /// Many rows or bytes returned, typically without a LIMIT.
    LargeResult,
    /// Statements that failed (the ORM may have swallowed the error).
    QueryErrors,
    /// One request ran a very large number of statements.
    ChattyRequest,
}

impl FindingKind {
    pub fn as_str(self) -> &'static str {
        match self {
            FindingKind::NPlusOne => "n_plus_one",
            FindingKind::DuplicateQuery => "duplicate_query",
            FindingKind::LoopedWrites => "looped_writes",
            FindingKind::PlanIssue => "plan_issue",
            FindingKind::SlowQuery => "slow_query",
            FindingKind::LargeResult => "large_result",
            FindingKind::QueryErrors => "query_errors",
            FindingKind::ChattyRequest => "chatty_request",
        }
    }
    pub fn label(self) -> &'static str {
        match self {
            FindingKind::NPlusOne => "N+1 query",
            FindingKind::DuplicateQuery => "Duplicate query",
            FindingKind::LoopedWrites => "Writes in a loop",
            FindingKind::PlanIssue => "Plan issue",
            FindingKind::SlowQuery => "Slow query",
            FindingKind::LargeResult => "Large result",
            FindingKind::QueryErrors => "Failing statement",
            FindingKind::ChattyRequest => "Chatty request",
        }
    }
}

/// A suggested change, written for the ORM in use when it is known.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct FixHint {
    /// `null` = generic advice.
    pub orm: Option<Orm>,
    pub text: String,
    pub code: Option<String>,
    /// Schema change to go with it, e.g. a `CREATE INDEX` or a migration snippet.
    pub ddl: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct CaptureFinding {
    /// Stable across captures: kind + fingerprint (used by baselines).
    pub id: String,
    pub kind: FindingKind,
    pub severity: SuggestionSeverity,
    pub title: String,
    pub detail: String,
    pub fingerprint: String,
    /// The statement that produced the rows being looped over (N+1), when known.
    pub parent_fingerprint: Option<String>,
    /// Statement time attributable to the problem, ms.
    pub impact_ms: f64,
    /// How many times the pattern occurred (loops, executions, failures…).
    pub occurrences: u32,
    pub origins: Vec<OriginCount>,
    pub fix: Option<FixHint>,
}

/// A candidate index tested against the planner.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct IndexCheck {
    pub ddl: String,
    pub evidence: Evidence,
    /// Cost (estimated) or median time in ms (measured), without / with the index.
    pub before: f64,
    pub after: f64,
    pub used: bool,
}

/// The plan of a captured statement, re-planned with the values it actually ran with.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct PlanCheck {
    pub fingerprint: String,
    pub mode: ExplainMode,
    /// The data access steps, e.g. "Seq Scan on order_items".
    pub shape: String,
    pub plan_fp: String,
    pub total_cost: Option<f64>,
    pub execution_ms: Option<f64>,
    pub warnings: Vec<PlanWarning>,
    pub index: Option<IndexCheck>,
    pub error: Option<String>,
}
